import{_ as d,a0 as a,w as p,s as u,ao as r,I as e,x as t,a1 as i,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"来聊聊： Windows vs. Linux | LCTT x X-CMD","titleTemplate":false,"description":"来聊聊： Windows vs. Linux | LCTT (201702) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"来聊聊： Windows vs. Linux | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"来聊聊： Windows vs. Linux | LCTT (201702) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201702/20170211 Lets Chat Windows vs. Linux","title":"来聊聊： Windows vs. Linux","tag":"201702","desc":""},"relativePath":"201702/20170211 Lets Chat Windows vs. Linux.md","filePath":"[post].md"}'),l={name:"201702/20170211 Lets Chat Windows vs. Linux.md"};function w(x,n,L,m,f,W){const s=a("Link");return p(),u("div",null,[n[13]||(n[13]=r('<h1 id="来聊聊-windows-vs-linux" tabindex="-1">来聊聊： Windows vs. Linux <a class="header-anchor" href="#来聊聊-windows-vs-linux" aria-label="Permalink to “来聊聊： Windows vs. Linux”">​</a></h1><blockquote><p>Windows 用户们，去还是留？</p></blockquote><p>Windows 依然是高居榜首的桌面操作系统，占据 90% 以上的市场份额，远超 macOS 和 Linux 。</p><p>从数据来看，尽管 linux 并不是 Windows 的头号接班人，但近几年越来越多用户转向 Ubuntu、Linux Mint 等发行版，的确为 Linux 带来了不小的增长。</p><p>面对 Windows 10 发布以来招致的诸多批评，微软后来采取的激进升级策略也明显无济于事。很多用户抱怨在不知情的情况下就被升级到了 Windows 10 ，这也促使部分用户决定放弃微软产品而转向 Linux 。</p><p>同时也有声音指责微软试图通过 Windows 10 监视用户，同样，这些批评助推更多用户投入 Linux 阵营。</p><h3 id="你怎么选-windows-or-linux" tabindex="-1">你怎么选： Windows or Linux？ <a class="header-anchor" href="#你怎么选-windows-or-linux" aria-label="Permalink to “你怎么选： Windows or Linux？”">​</a></h3><p>十几年前，用户转向 Linux 还主要是出于安全考虑，因为 Windows 才是全世界病毒和黑客的主要攻击目标。</p><p>这有它的必然原因： Windows 是被最广泛采用的操作系统，但那时微软在安全上的设计并没有今天这样实用。</p><p>而近几年，尽管 Linux 和 Windows 在安全方面的差距已没有那么明显，但那些决定转阵营的用户似乎又有了除安全以外的其它理由。</p><p>我们不想用什么市场统计来说明问题，因为在这场 Windows 和 Linux 的持久战中，这些数据显得无关紧要。但是用户的声音却至关重要，因为它们总能代表并预示各个平台的走向。</p><p>这也是为什么我们在这里向读者提出问题： Linux 是 Windows 合适的替代品么？放弃 Windows 而选择 Linux 是否明智？微软是否该为用户流向 Linux 而感到紧张？请在评论中留下您的看法。</p><hr>',13)),e("p",null,[n[1]||(n[1]=t("via: ",-1)),i(s,{href:"http://news.softpedia.com/news/let-s-chat-windows-vs-linux-512842.shtml"},{default:o(()=>[...n[0]||(n[0]=[t("http://news.softpedia.com/news/let-s-chat-windows-vs-linux-512842.shtml",-1)])]),_:1})]),e("p",null,[n[5]||(n[5]=t("作者：",-1)),i(s,{href:"http://news.softpedia.com/editors/browse/bogdan-popa"},{default:o(()=>[...n[2]||(n[2]=[t("Bogdan Popa",-1)])]),_:1}),n[6]||(n[6]=t(" 译者：",-1)),i(s,{href:"https://github.com/Dotcra"},{default:o(()=>[...n[3]||(n[3]=[t("Dotcra",-1)])]),_:1}),n[7]||(n[7]=t(" 校对：",-1)),i(s,{href:"https://github.com/wxy"},{default:o(()=>[...n[4]||(n[4]=[t("wxy",-1)])]),_:1})]),e("p",null,[n[10]||(n[10]=t("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...n[8]||(n[8]=[t("LCTT",-1)])]),_:1}),n[11]||(n[11]=t(" 原创编译，",-1)),i(s,{href:"https://linux.cn/"},{default:o(()=>[...n[9]||(n[9]=[t("Linux中国",-1)])]),_:1}),n[12]||(n[12]=t(" 荣誉推出",-1))])])}const h=d(l,[["render",w]]);export{v as __pageData,h as default};
